    def fmt(k, A):
        return f"{len(A)} {k}\n" + ' '.join(map(str, A))

    tests = [fmt(1, [0]), fmt(1, [1]), fmt(2, [1]), fmt(1, [1, 0]), fmt(1, [0, 1, 0]), fmt(2, [3, 0]),
             fmt(2, [0, 0, 0]), fmt(2, [3, 3, 3]), fmt(3, [5, 2, 7, 0])]
    for n, k in ((1, 3), (2, 2), (2, 3), (3, 2), (3, 3), (4, 2), (4, 3), (5, 1), (5, 2), (6, 1)):
        for _ in range(2):
            tests.append(fmt(k, [rng.randint(0, (1 << k) - 1) for _ in range(n)]))
    N, K = 100000, 20
    tests.append(fmt(K, [rng.randint(0, (1 << K) - 1) for _ in range(N)]))
    tests.append(fmt(K, [((1 << K) - 1) if i < N // 2 else 0 for i in range(N)]))
    tests.append(fmt(K, [(1 << K) - 1] * N))
    tests.append(fmt(K, [0] * N))
    tests.append(fmt(K, [rng.randint(0, (1 << K) - 1) | rng.randint(0, (1 << K) - 1) for _ in range(N)]))
    return tests

